import{z as s,x as d,o as E,c as p,q as i,j as r,D as e,d as t,s as A,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"财报滞后与可用日期","description":"","frontmatter":{"title":"财报滞后与可用日期","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/filing-lag-available-date.md","filePath":"quant/filing-lag-available-date.md","lastUpdated":1791063341000}'),B={name:"quant/filing-lag-available-date.md"};function m(h,a,u,F,c,f){const l=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=i('<h1 id="财报滞后与可用日期" tabindex="-1">财报滞后与可用日期 <a class="header-anchor" href="#财报滞后与可用日期" aria-label="Permalink to &quot;财报滞后与可用日期&quot;">​</a></h1><div class="epigraph"><p>报告期在 12 月 31 日结束，并不等于 1 月 2 日就能交易这笔数字；可用日期是市场第一次公开读到报表的日历日。</p><footer>—— 据 Fama and French, Journal of Financial Economics, 1993 因子构造说明；SEC 申报期限与 Compustat 公告日字段整理</footer></div><p>上一课<a href="/quant/pit-fundamentals">Point-in-time 基本面</a>把 as-of 写成记录级约束。仍缺日历：公告日从哪来、法定截止不等于实际披露、季报与年报滞后不同。本课把 PIT 收成可执行的<strong>可用日期</strong>。下一课才处理谁从样本里消失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PIT 说「只用当时存在的版本」，但版本何时存在？用 period_end 会提前一到四个月；用 vendor 的 last_updated 会把后来修订的时间戳污染历史；用法定申报截止日（美国 10-K 的 60/75/90 天档）会把提前披露的公司推迟、把逾期公司提前。缺口是给每条记录一个<strong>市场可读取日</strong> \\(d^{avail}\\)，信号日 \\(t\\) 只读 \\(d^{avail}\\le t\\)。</p><p>Fama–French 用 \\(t\\) 年 6 月的市值配 \\(t-1\\) 财年账面，把滞后写成组合日历上的粗规则。事件研究与日频因子没有这份奢侈：同一周里，有的公司已发 8-K，有的还在静默期。没有可用日期，截面排序在比较「已披露」与「尚未披露」的公司。</p><p><span class="marginnote">数字实例：一家公司财年止于 12 月 31 日、次年 3 月 1 日才发 10-K。若 1 月 2 日就把年报利润用于选股，你「提前」交易了 59 天——这段提前量在回测里常常是全部超额收益的来源，实盘一分都拿不到。</span></p><h3 id="公告日不是财报截止日" tabindex="-1">公告日不是财报截止日 <a class="header-anchor" href="#公告日不是财报截止日" aria-label="Permalink to &quot;公告日不是财报截止日&quot;">​</a></h3><p>fiscal period end 是会计期间的右端点。filing date / earnings announcement date 才是信息进入价格的候选时点。两者相差的「滞后」本身可交易，但本课先当数据约束，不当 alpha。把截止日当公告日，等于假设所有公司在法定最后一天同时披露——这与事实相反，也与后课公告窗口研究直接冲突。</p><p><span class="marginnote">IBES 与 Compustat 的公告日字段会对不齐。事件研究要用更干净的公告时点；截面因子至少要一个不晚于真实披露的截断日。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每条基本面记录存 \\(d^{avail}\\)。优先顺序：交易所/监管公告时间戳；其次 vendor 的 rdq / filedate；再次用法定截止日作上界并加缓冲。周末与休市：可用日期落到下一交易日，避免把周五盘后公告写进周五收盘信号。季报滞后短、年报滞后长，同一公司不要套一个全局 \\(k\\)。</p><p>Fama–French 的六月规则可以保留为价值因子的稳健默认，但应计、盈利、惊喜类日频信号必须用记录级 \\(d^{avail}\\)。后课<a href="/quant/earnings-announcement-window">财报公告窗口</a>会把 \\(d^{avail}\\) 当成事件日；本课只要求它先存在、且不前视。</p>',13)),(E(),r(o,null,{default:e(()=>[A(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E6%8A%A5%E5%91%8A%E6%9C%9F%E7%BB%93%E6%9D%9F%22%5D%20--%3E%20LAG%5B%22%E6%8A%AB%E9%9C%B2%E6%BB%9E%E5%90%8E%22%5D%0A%20%20LAG%20--%3E%20AVAIL%5B%22%E5%8F%AF%E7%94%A8%E6%97%A5%E6%9C%9F%22%5D%0A%20%20AVAIL%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E6%97%A5%E5%8F%AF%E8%AF%BB%E5%8F%96%22%5D%0A%20%20END%20-.-%3E%7C%22%E8%AF%AF%E7%94%A8%E6%88%AA%E6%AD%A2%E6%97%A5%22%7C%20EARLY%5B%22%E6%8F%90%E5%89%8D%E4%BA%A4%E6%98%93%E5%B9%BB%E8%A7%89%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"滞后制造两种回测偏差。一种是抢跑：用尚未公开的季报算当季因子。一种是错位比较：已披露公司与未披露公司排在同一截面，排序混进了「披露状态」。可用日期把公司从「有数字」集合里按时点放进、放出。静默期、业绩预告、修正公告是同一机制的多次到达：每次到达更新 \\(d^{avail}\\) 与当时版本，而不是覆盖历史。",-1)),(E(),r(o,null,{default:e(()=>[A(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NO%5B%22%E6%B2%A1%E6%9C%89%20d_avail%20%E7%9A%84%E5%9B%9E%E6%B5%8B%22%5D%20--%3E%20B1%5B%22%E5%81%8F%E5%B7%AE%E4%B8%80%EF%BC%9A%E6%8A%A2%E8%B7%91%22%5D%0A%20%20NO%20--%3E%20B2%5B%22%E5%81%8F%E5%B7%AE%E4%BA%8C%EF%BC%9A%E9%94%99%E4%BD%8D%E6%AF%94%E8%BE%83%22%5D%0A%20%20B1%20--%3E%20E1%5B%22%E7%94%A8%E6%9C%AA%E5%85%AC%E5%BC%80%E5%AD%A3%E6%8A%A5%E7%AE%97%E5%BD%93%E6%9C%9F%E5%9B%A0%E5%AD%90%EF%BC%9A%E5%87%AD%E7%A9%BA%20alpha%22%5D%0A%20%20B2%20--%3E%20E2%5B%22%E5%B7%B2%E6%8A%AB%E9%9C%B2%E4%B8%8E%E6%9C%AA%E6%8A%AB%E9%9C%B2%E5%85%AC%E5%8F%B8%E5%90%8C%E4%B8%80%E6%88%AA%E9%9D%A2%E6%8E%92%E5%BA%8F%22%5D%0A%20%20E1%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%EF%BC%9A%E8%AE%B0%E5%BD%95%E7%BA%A7%20d_avail%20%E2%89%A4%20t%20%E6%89%8D%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20E2%20--%3E%20FIX%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">术语翻译：「静默期、业绩预告、修正公告」用版本语言说，就是同一份财报信息分几次敲门。\\(d^{avail}\\) 的正确用法是每次敲门都新增一条带时间戳的版本记录，而不是回头改写旧记录——旧记录是当时的真实世界。</span></p><p><span class="marginnote">盘后公告归属哪一个交易日，要与后课窗口研究的约定一致。本课只要求：回测里写死一条规则，并与价格复权日历对齐。</span></p><p>盘后与盘前要写进同一条规则，并与价格日历的时区一致。美股常用「16:00 之后算下一交易日」；A 股公告常在晚间，同样归次日。事件研究与截面因子必须共用这条归属，否则同一份财报在两个管道里是两个事件日。法定截止日只作缺失公告日时的上界，且应加缓冲，切勿把上界当成真实披露。滞后分布本身可以做研究，但本课先当约束，不当 alpha。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不比较各国法定天数表，不写监管法条。EDGAR 与新闻社的分钟级时差交给事件研究，不在此做成高频。下一课<a href="/quant/survivorship-delist">幸存者与退市</a>处理样本进出，不处理披露时钟。后课默认：每个基本面字段带可用日期；六月规则只是年频价值因子的特例。</p><p>后课公告窗口、惊喜、事件策略全部复用本课的 \\(d^{avail}\\) 归属规则；中途改盘后定义等于改写历史事件日。缺失公告日时用法定截止加缓冲，并在结果里报告缺失比例。不要用 vendor 最后更新时间替代公告日，那会把修订写进第一次披露。</p><p><span class="marginnote">常见误区：把 vendor 的 last_updated 当公告日。数据库会因更正、拆分调整、重述反复刷新这个时间戳；拿它当首次披露日，等于让 2008 年的修订「穿越」回 2005 年的信号里。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIT 约束版本；本课给版本一个可读取的日历日。</li><li>报告期结束、法定截止、公告日是三个不同时点。</li><li>固定月数滞后是代理；记录级可用日期才可进日频信号。</li><li>Fama–French 六月规则是粗滞后，不是 PIT 的替代定义。</li><li>公告窗口研究将复用本课的可用日期当事件日。</li><li>出处：Fama–French (1993) 构造说明；SEC 申报期限；Compustat 公告日字段。</li></ul>',9))])}const _=s(B,[["render",m]]);export{C as __pageData,_ as default};
